/**
 * The workflow orchestrator (SPINE-1 §5.4) — TS port of `GuardEvaluator`. Evaluates a
 * transition guard / action condition (a one-node graph) over a flat context bag.
 * Fail-closed: a pending/errored guard does not let a transition fire.
 */
import { admissionRefusal, type EvaluationAdmission } from './environment.js'
import { Codes } from './codes.js'
import type { ComputedValue, Json, RuleDefinition, Validity } from './model.js'
import { DEFAULT_LIMITS, type RuleEngineLimits } from './limits.js'
import { compile } from './compiler.js'
import { CompileError } from './grammar.js'
import {
  EvalBudget, RuleBudget, RuleEvalError, RulePending,
  err, refError, refPending, refResolved, unavailableAggregate,
  type EvalContext, type RefValue, type ValueResolver,
} from './eval-support.js'
import { evaluate, isTruthy } from './jsonlogic.js'
import { parseBoundedJsonText } from './input-envelope.js'
import { detachJson } from './instance.js'

const isPendingSentinel = (n: Json): boolean =>
  typeof n === 'object' && n !== null && !Array.isArray(n) &&
  Object.keys(n).length === 1 && (n as Record<string, Json>)['@pending'] === true

class ContextBagResolver implements ValueResolver {
  constructor(private readonly bag: Record<string, Json>) {}

  resolveVar(path: string): RefValue {
    if (path.startsWith('row.')) return refError(err(Codes.badReference, 'path', path))
    const name = path.startsWith('field.') ? path.slice('field.'.length) : path
    if (Object.hasOwn(this.bag, name)) {
      const v = this.bag[name]
      return isPendingSentinel(v) ? refPending : refResolved(v)
    }
    return refResolved(null)
  }

  resolveAgg(fn: string, section: string, col: string): RefValue {
    // A flat context bag carries no tables: every aggregate is unavailable data (ticket 162's
    // one shared refusal shape — the corpus pins its params across tiers).
    return unavailableAggregate(fn, section, col)
  }
}

/**
 * The workflow-guard context as a {@link ContextAdapter} (ADR 0146 D3): maps a flat process /
 * context bag into a `ContextBagResolver`. The bag has no repeating sub-collection, so the
 * scope's `rowSection` is ignored (a `row.` reference resolves to a bad-reference, as before).
 */
const snapshotBrand = new WeakSet<object>()
const snapshotData = new WeakMap<object, Record<string, Json>>()
/**
 * Runtime-owned data admitted from JSON text before crossing into pure evaluation.
 * Parsing belongs to the host boundary; evaluator entry never reflects over a caller object.
 */
export class RuleContextSnapshot {
  // No constructor arguments or instance data: JavaScript callers can invoke a TS-private
  // constructor, but only this module's JSON-text factory can add owned data to the WeakMap.
  private constructor() {}

  static fromJsonText(jsonText: string): RuleContextSnapshot {
    const parsed: unknown = parseBoundedJsonText(jsonText, 'rule context')
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) throw new TypeError('rule context must be a JSON object')
    const snapshot = new RuleContextSnapshot()
    snapshotBrand.add(snapshot)
    snapshotData.set(snapshot, parsed as Record<string, Json>)
    return snapshot
  }
}

function contextValuesOf(value: unknown): Record<string, Json> | undefined {
  return typeof value === 'object' && value !== null && snapshotBrand.has(value)
    ? snapshotData.get(value)
    : undefined
}

export class GuardEvaluator {
  constructor(
    private readonly clock: () => Date,
    private readonly limits: RuleEngineLimits = DEFAULT_LIMITS,
  ) {
    if (typeof clock !== 'function') throw new TypeError('GuardEvaluator requires a caller-supplied clock')
  }

  evaluateGuard(rule: RuleDefinition, context: RuleContextSnapshot, admission: EvaluationAdmission | null, signal?: AbortSignal): Validity {
    let compiled: ReturnType<typeof compile>
    try { compiled = compile([rule], this.limits) }
    catch (error) {
      if (error instanceof CompileError) return { ok: false, error: err(error.code) }
      throw error
    }
    // rules-eng-26: admission evidence is checked before any value is read.
    const refusal = admissionRefusal(admission, compiled.rules.map((r) => r.ast))
    if (refusal !== null) return { ok: false, error: err(refusal) }
    const snapshot = contextValuesOf(context)
    if (!snapshot) return { ok: false, error: err(Codes.contextSnapshotRequired) }
    if (compiled.rules.length === 0) return { ok: true } // Tier-1 guard: nothing for this engine.
    return this.run<Validity>(
      compiled.rules[0].ast as Json,
      rule.id,
      snapshot,
      (v) => (isTruthy(v) ? { ok: true } : { ok: false, error: err(rule.id) }),
      (e) => ({ ok: false, error: e }),
      () => ({ ok: false, error: err(Codes.pendingAtSave) }),
      signal,
    )
  }

  evaluateValue(rule: RuleDefinition, context: RuleContextSnapshot, admission: EvaluationAdmission | null, signal?: AbortSignal): ComputedValue {
    let compiled: ReturnType<typeof compile>
    try { compiled = compile([rule], this.limits) }
    catch (error) {
      if (error instanceof CompileError) return { state: 'Error', error: err(error.code) }
      throw error
    }
    const refusal = admissionRefusal(admission, compiled.rules.map((r) => r.ast))
    if (refusal !== null) return { state: 'Error', error: err(refusal) }
    const snapshot = contextValuesOf(context)
    if (!snapshot) return { state: 'Error', error: err(Codes.contextSnapshotRequired) }
    if (compiled.rules.length === 0) return { state: 'Resolved', value: null }
    return this.run<ComputedValue>(
      compiled.rules[0].ast as Json,
      rule.id,
      snapshot,
      (v) => ({ state: 'Resolved', value: detachJson(v) }),
      (e) => ({ state: 'Error', error: e }),
      () => ({ state: 'Pending' }),
      signal,
    )
  }

  private run<T>(
    ast: Json,
    ruleId: string,
    context: Record<string, Json>,
    onValue: (v: Json) => T,
    onError: (e: ReturnType<typeof err>) => T,
    onPending: () => T,
    signal?: AbortSignal,
  ): T {
    const ctx: EvalContext = { resolver: new ContextBagResolver(context), now: this.clock(), budget: new EvalBudget(this.limits, signal) }
    try {
      return onValue(evaluate(ast, ctx))
    } catch (e) {
      if (e instanceof RuleEvalError) return onError(e.error)
      if (e instanceof RulePending) return onPending()
      if (e instanceof RuleBudget) return onError(err(Codes.budgetExceeded, 'rule', ruleId))
      // RuleTimeout is a non-authoritative liveness fault (D1 ratification 2026-07-01): a guard that hits
      // the wall-clock is an infrastructure fault, not a transition verdict — it PROPAGATES (rethrown).
      throw e
    }
  }
}

src/__tests__/definition-admission.test..source:
import { describe, expect, it } from 'vitest'

import { compile } from '../compiler.js'
import { Codes } from '../codes.js'
import { FormRuleGraph } from '../graph.js'
import { RuleInstance } from '../instance.js'
import { DEFAULT_LIMITS } from '../limits.js'
import type { Json, RuleDefinition } from '../model.js'
import { admitEnvironment as admitTestEnvironment, fieldReadEffect as testFieldRead, lentGrammar as testGrammar } from '../environment.js'
import { builtInFunctions as testBuiltIns } from '../functions.js'
// The suite's own borrower: the whole register, every scope token, every phase (T-590 rules-eng-26).
const testAdmission = admitTestEnvironment({ borrower: 'rule-engine-tests', grammar: testGrammar, variables: { field: 'test', row: 'test', wf: 'test', timer: 'test' }, operations: testBuiltIns.map((f) => f.key), effects: [testFieldRead], missingValues: 'missing-field-reads-null', timeSource: 'injected-test-clock', timeZone: 'utc', phases: { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }, replay: 'deterministic' }).forPhase('Run')

function compute(id: string, target: string, expression: Json): RuleDefinition {
  return { id, tier: 'JsonLogic', scope: 'Field', scopeTarget: target, action: 'Compute', expression }
}

describe('definition compiler admission', () => {
  it.each([
    { unknown_operator: [] },
    { regex: ['a', '.*'] },
    { if: [false, { unknown_operator: [] }, true] },
  ])('rejects unsupported executable syntax before any records are evaluated: %j', expression => {
    expect(() => compile([compute('closed-grammar', 'total', expression)])).toThrow(expect.objectContaining({
      code: Codes.compileInvalidExpression,
      ruleId: 'closed-grammar',
    }))
  })

  it.each([
    { expression: [{ unknown_operator: [] }] },
    { expression: { metadata: { unknown_operator: [] }, label: 'literal' } },
  ])('does not interpret literal data as executable syntax: %j', ({ expression }) => {
    expect(compile([compute('literal-data', 'result', expression)]).rules).toHaveLength(1)
  })

  it.each([
    { 'date.today': ['unexpected'] },
    { 'coding.is': [{ var: 'code' }, 'system'] },
  ])('rejects invalid executable arity before any records are evaluated: %j', expression => {
    expect(() => compile([compute('invalid-arity', 'result', expression)])).toThrow(expect.objectContaining({
      code: Codes.compileInvalidExpression,
      ruleId: 'invalid-arity',
    }))
  })

  it.each(['mystery', '', 99, null])('refuses unknown tier %s instead of interpreting it as JsonLogic', tier => {
    const source = { ...compute('unknown-tier', 'total', 1), tier } as RuleDefinition

    expect(() => compile([source])).toThrow(expect.objectContaining({
      code: Codes.compileUnsupportedTier,
      ruleId: 'unknown-tier',
    }))
  })

  it.each(['mystery', '', 99, null])('refuses unknown action %s instead of interpreting it as Visibility', action => {
    const source = { ...compute('unknown-action', 'total', true), action } as RuleDefinition

    expect(() => compile([source])).toThrow(expect.objectContaining({
      code: 'rule.compile.unknown_action',
      ruleId: 'unknown-action',
    }))
  })

  it.each([64, 65])('enforces the inclusive reference boundary at %i', count => {
    const expression = { '+': Array.from({ length: count }, (_, i) => ({ var: `r${i}` })) }
    const source = compute('reference-boundary', 'total', expression)

    if (count === 64) expect(compile([source]).rules).toHaveLength(1)
    else expect(() => compile([source])).toThrow(expect.objectContaining({ code: Codes.compileTooManyRefs }))
  })

  it.each([64, 65])('enforces the inclusive dependency boundary at %i', depth => {
    const sources = Array.from({ length: depth }, (_, i) =>
      compute(`dependency-${i}`, `f${i}`, { var: `f${i + 1}` }))

    if (depth === 64) expect(compile(sources).rules).toHaveLength(64)
    else expect(() => compile(sources)).toThrow(expect.objectContaining({ code: Codes.compileDepthExceeded }))
  })

  it('enforces AST and literal boundaries at and immediately over their configured limit', () => {
    const astLimits = { ...DEFAULT_LIMITS, maxAstNodes: 1 }
    expect(compile([compute('ast-at', 'x', 1)], astLimits).rules).toHaveLength(1)
    expect(() => compile([compute('ast-over', 'x', { '!': [true] })], astLimits))
      .toThrow(expect.objectContaining({ code: Codes.compileAstTooLarge }))

    const literalLimits = { ...DEFAULT_LIMITS, maxLiteralLength: 1 }
    expect(compile([compute('literal-at', 'x', '"a"')], literalLimits).rules).toHaveLength(1)
    expect(() => compile([compute('literal-over', 'x', '"ab"')], literalLimits))
      .toThrow(expect.objectContaining({ code: Codes.compileLiteralTooLong }))
  })

  it('derives empty, literal, and short dependency programs without host-depth iteration', () => {
    const large = { ...DEFAULT_LIMITS, maxDependencyDepth: 2_147_483_647 }
    expect(compile([], large).workProof.maximumEvaluationWork).toBeGreaterThanOrEqual(0n)
    expect(compile([compute('literal', 'x', 1)], large).workProof.maximumResultBytes).toBeGreaterThanOrEqual(1n)
    expect(compile([compute('a', 'a', { var: 'b' }), compute('b', 'b', 1)], large).rules).toHaveLength(2)
  })

  it('bounds one dynamic computed cell independently of unused graph capacity', () => {
    const rules = [compute('dynamic', 'result', { missing: [{ var: 'keys' }] })]
    const oneCell = compile(rules, { ...DEFAULT_LIMITS, maxGraphNodes: 1 }).workProof
    const defaultCapacity = compile(rules).workProof

    expect(defaultCapacity.maximumResultBytes === oneCell.maximumResultBytes).toBe(true)
    expect(defaultCapacity.maximumEvaluationWork === oneCell.maximumEvaluationWork).toBe(true)
  })

  it('increases the dynamic demand bound when an actual computed cell is added', () => {
    const dynamic = compute('dynamic', 'result', { missing: [{ var: 'keys' }] })
    const oneCell = compile([dynamic]).workProof
    const twoCells = compile([dynamic, compute('second', 'second', 1)]).workProof

    expect(twoCells.maximumResultBytes).toBe(oneCell.maximumResultBytes)
    expect(twoCells.maximumEvaluationWork > oneCell.maximumEvaluationWork).toBe(true)
  })

  it('includes an aggregate cell in a dynamic proof and accounts for producing its result', () => {
    const dynamic = compute('dynamic', 'result', { missing: [{ var: 'keys' }] })
    const oneCell = compile([dynamic]).workProof
    const aggregateRule: RuleDefinition = {
      ...compute('aggregate', 'check', { '==': [{ var: 'table.sum(items.amount)' }, 0] }),
      action: 'Validate',
    }
    const withAggregate = compile([dynamic, aggregateRule]).workProof
    const withSecondCompute = compile([dynamic, compute('second', 'second', 1)]).workProof

    expect(withAggregate.maximumResultBytes).toBe(oneCell.maximumResultBytes)
    expect(withAggregate.maximumResultBytes === withSecondCompute.maximumResultBytes).toBe(true)
    expect(oneCell.maximumEvaluationWork >= oneCell.maximumResultBytes).toBe(true)
  })

  it('does not copy dynamically inspected values into a Row missing result', () => {
    const row: RuleDefinition = {
      ...compute('row', 'items/calculated', { missing: [{ var: 'rowKeys' }] }),
      scope: 'Row',
    }
    const oneRow = compile([row], { ...DEFAULT_LIMITS, maxGraphNodes: 1, maxTableRowsPerAggregate: 2 }).workProof
    const twoRows = compile([row], { ...DEFAULT_LIMITS, maxGraphNodes: 2, maxTableRowsPerAggregate: 2 }).workProof

    expect(twoRows.maximumResultBytes).toBe(oneRow.maximumResultBytes)
    expect(twoRows.maximumEvaluationWork).toBeGreaterThan(oneRow.maximumEvaluationWork)
  })

  it('instantiates a proof for independently configured graph structural dimensions', () => {
    const compiled = compile([compute('row-aware', 'x', { var: 'table.sum(items.amount)' })],
      { ...DEFAULT_LIMITS, maxTableRowsPerAggregate: 1, maxGraphNodes: 2 })
    const graph = new FormRuleGraph(compiled, () => new Date('2026-09-22T00:00:00Z'), testAdmission,
      { ...DEFAULT_LIMITS, maxTableRowsPerAggregate: 2, maxGraphNodes: 3 })
    graph.evaluateInstance(RuleInstance.fromJsonText('{}'))
    expect(graph.workProof.maximumResultBytes).toBeGreaterThanOrEqual(compiled.workProof.maximumResultBytes)
  })

  it('captures mutable runtime structural limits with its instantiated proof', () => {
    const sourceLimits = { ...DEFAULT_LIMITS, maxGraphNodes: 1, maxTableRowsPerAggregate: 1 }
    const graph = new FormRuleGraph(compile([compute('one', 'x', 1)]), () => new Date('2026-09-22T00:00:00Z'), testAdmission, sourceLimits)
    const proof = graph.workProof
    sourceLimits.maxGraphNodes = 0
    sourceLimits.maxTableRowsPerAggregate = 0

    expect(graph.workProof).toBe(proof)
    expect(graph.evaluateInstance(RuleInstance.fromJsonText('{}')).values.get('field:x')).toEqual({ state: 'Resolved', value: 1 })
  })

  it('composes a known array-producing rule into a downstream scalar admission', () => {
    expect(() => compile([
      compute('array', 'array', []),
      compute('scalar', 'scalar', { '+': [{ var: 'array' }, 1] }),
    ])).toThrow(expect.objectContaining({ code: Codes.compileInvalidExpression, ruleId: 'scalar' }))
  })

  it('publishes a finite compositional result/work proof that bounds an executed copying expression', () => {
    const graph = compile([
      compute('copying-cat', 'result', { cat: ['ab', { cat: ['cd', 'ef'] }] }),
    ])
    const evaluated = new FormRuleGraph(graph, () => new Date('2026-09-22T00:00:00.000Z'), testAdmission)
      .evaluateInstance(RuleInstance.fromJsonText('{}'))
    const value = evaluated.values.get('field:result')

    expect(value).toEqual({ state: 'Resolved', value: 'abcdef' })
    expect(graph.workProof.maximumResultBytes).toBeGreaterThanOrEqual(6)
    expect(graph.workProof.maximumEvaluationWork).toBeGreaterThan(0)
  })

  it('bounds a Table Compute value copied through an aggregate reference', () => {
    const aggregate = { var: 'table.sum(items.amount)' }
    const rules: RuleDefinition[] = [
      { ...compute('table-value', 'items/sum/amount', { var: 'payload' }), scope: 'Table' },
      compute('copies', 'result', { cat: Array.from({ length: 10 }, () => aggregate) }),
    ]
    const limits = { ...DEFAULT_LIMITS, maxTableRowsPerAggregate: 1, stepBudget: 10_000_000 }
    const compiled = compile(rules, limits)
    const result = new FormRuleGraph(compiled, () => new Date('2026-09-22T00:00:00.000Z'), testAdmission, limits)
      .evaluateInstance(RuleInstance.fromJsonText(JSON.stringify({ payload: 'x'.repeat(80_000) })))
    const value = result.values.get('field:result')

    expect(value?.state).toBe('Resolved')
    expect(compiled.workProof.maximumResultBytes).toBeGreaterThanOrEqual(
      BigInt(new TextEncoder().encode(JSON.stringify(value?.value)).length))
  })

  it('keeps the larger Table bound when an admitted duplicate target is replaced', () => {
    const rules: RuleDefinition[] = [
      { ...compute('small-table', 'items/sum/amount', '"a"'), scope: 'Table' },
      { ...compute('large-table', 'items/sum/amount', { var: 'payload' }), scope: 'Table' },
      compute('copies', 'result', { cat: Array.from({ length: 10 }, () => ({ var: 'table.sum(items.amount)' })) }),
    ]
    const limits = { ...DEFAULT_LIMITS, maxTableRowsPerAggregate: 1, stepBudget: 10_000_000 }
    const compiled = compile(rules, limits)
    const result = new FormRuleGraph(compiled, () => new Date('2026-09-22T00:00:00.000Z'), testAdmission, limits)
      .evaluateInstance(RuleInstance.fromJsonText(JSON.stringify({ payload: 'x'.repeat(80_000) })))
    const value = result.values.get('field:result')

    expect(value?.state).toBe('Resolved')
    expect(compiled.workProof.maximumResultBytes).toBeGreaterThanOrEqual(
      BigInt(new TextEncoder().encode(JSON.stringify(value?.value)).length))
  })

  // Compiles and runs 8 KB decimals: ~0.9 s locally, just over vitest's 5 s default on hosted macOS runners.
  // The assertions are byte bounds, not speed, so the timeout is explicit.
  it('bounds the public large aligned-money concatenation in serialized JSON bytes', () => {
    const integer = '9'.repeat(4090)
    const fraction = `0.${'0'.repeat(4088)}1`
    const graph = compile([
      compute('aligned-money-cat', 'result', {
        cat: Array.from({ length: 60 }, () => ({ 'money.add': [integer, fraction] })),
      }),
    ])
    // Deliberately diagnostic-only: this is not a production limit change. The wall clock is the
    // non-authoritative liveness guard; 5 s tripped RuleTimeout on hosted macOS runners, so it sits
    // under the test's 30 s timeout instead. The step budget stays the authoritative bound.
    const limits = { ...DEFAULT_LIMITS, stepBudget: 2_000_000, wallClockMs: 25_000 }
    const evaluated = new FormRuleGraph(graph, () => new Date('2026-09-22T00:00:00.000Z'), testAdmission, limits)
      .evaluateInstance(RuleInstance.fromJsonText('{}'))
    const value = evaluated.values.get('field:result')

    expect(value?.state).toBe('Resolved')
    const actualBytes = new TextEncoder().encode(JSON.stringify(value?.value)).length
    expect(actualBytes).toBe(490802)
    expect(graph.workProof.maximumResultBytes).toBeGreaterThanOrEqual(BigInt(actualBytes))
  }, 30_000)

  it('bounds JSON re-escaping and the empty boolean/date identities through execution', () => {
    const graph = compile([
      compute('quoted-container-cat', 'quoted', { cat: [{ label: '"quoted"', values: ['x'] }, { 'date.today': [] }] }),
      compute('empty-cat', 'emptyCat', { cat: [] }),
      compute('empty-and', 'emptyAnd', { and: [] }),
      compute('empty-or', 'emptyOr', { or: [] }),
      compute('strict-inequality', 'different', { '!==': [1, '1'] }),
    ])
    const result = new FormRuleGraph(graph, () => new Date('2026-09-22T00:00:00.000Z'), testAdmission)
      .evaluateInstance(RuleInstance.fromJsonText('{}'))
    const values = ['field:quoted', 'field:emptyCat', 'field:emptyAnd', 'field:emptyOr', 'field:different']
      .map(key => result.values.get(key)?.value)

    expect(values.slice(1)).toEqual(['', true, false, true])
    expect(graph.workProof.maximumResultBytes).toBeGreaterThanOrEqual(BigInt(Math.max(
      ...values.map(value => new TextEncoder().encode(JSON.stringify(value)).length),
    )))
  })

  it('accepts trimmed money decimals but refuses exponent text through the executed evaluator', () => {
    const graph = new FormRuleGraph(compile([
      compute('trimmed-money', 'trimmed', { 'money.add': [' 1.20 ', '2.30'] }),
      compute('exponent-money', 'exponent', { 'money.add': ['1e2', '1'] }),
    ]), () => new Date('2026-09-22T00:00:00.000Z'), testAdmission)
    const result = graph.evaluateInstance(RuleInstance.fromJsonText('{}'))

    expect(result.values.get('field:trimmed')).toEqual({ state: 'Resolved', value: '3.5' })
    expect(result.values.get('field:exponent')).toMatchObject({ state: 'Error', error: { code: Codes.typeError } })
  })

  it('refuses all-whitespace money text through the public evaluator', () => {
    const graph = new FormRuleGraph(compile([
      compute('blank-money', 'blank', { 'money.add': ['   ', '1'] }),
    ]), () => new Date('2026-09-22T00:00:00.000Z'), testAdmission)
    const result = graph.evaluateInstance(RuleInstance.fromJsonText('{}'))

    expect(result.values.get('field:blank')).toMatchObject({ state: 'Error', error: { code: Codes.typeError } })
  })
})

