/**
 * The dual-tier conformance harness, TS side (SPINE-1 §6.1, §6.4). Loads the SAME
 * shared JSON corpus the .NET test project loads, runs each case through the TS engine,
 * and asserts the lowered AST + per-rule outcomes match byte-for-byte (canonical JSON).
 * Both tiers asserting against the one corpus is what proves the two evaluators agree.
 */
import { describe, it, expect } from 'vitest'
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

import type { Json, RuleDefinition } from '../model.js'
import { compile } from '../compiler.js'
import { CompileError } from '../grammar.js'
import { FormRuleGraph } from '../graph.js'
import { GuardEvaluator, RuleContextSnapshot } from '../guard.js'
import { RuleInstance } from '../instance.js'
import { serializeComputedValue, serializeOutcome, write } from '../canonical.js'
import {
  compileDecisionTable,
  compileFormula,
  type DecisionCell,
  type DecisionTableSkin,
  type FormulaSkin,
  type NoMatch,
} from '../skins/index.js'
import { admitEnvironment as admitTestEnvironment, fieldReadEffect as testFieldRead, lentGrammar as testGrammar } from '../environment.js'
import { builtInFunctions as testBuiltIns } from '../functions.js'
// The suite's own borrower: the whole register, every scope token, every phase (T-590 rules-eng-26).
const testAdmission = admitTestEnvironment({ borrower: 'rule-engine-tests', grammar: testGrammar, variables: { field: 'test', row: 'test', wf: 'test', timer: 'test' }, operations: testBuiltIns.map((f) => f.key), effects: [testFieldRead], missingValues: 'missing-field-reads-null', timeSource: 'injected-test-clock', timeZone: 'utc', phases: { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }, replay: 'deterministic' }).forPhase('Run')

const here = dirname(fileURLToPath(import.meta.url))
const corpusDir = join(here, '..', '..', '..', '..', '..', '..', 'conformance', 'hlp.foundation.rule-runtime', 'corpus')
const artifactDir = join(here, '..', '..', '..', '..', '..', '..', 'artifacts', 'rule-runtime')

interface CorpusCase {
  name: string
  clock?: string
  limits?: Record<string, number>
  definitionRules?: Array<Record<string, Json>>
  skin?: Record<string, Json>
  instance: Record<string, Json>
  expectedAst?: Record<string, Json>
  expectedCompiledExpression?: Record<string, Json>
  expectedOutcomes?: Record<string, Json>
  /** Ticket 162: the case pins a PUBLISH-TIME refusal — compile must throw this stable code. */
  expectedCompileError?: { code: string }
  /** Ticket 162: evaluate this rule id through GuardEvaluator.evaluateValue over `instance` as the context bag. */
  guardValue?: string
  expectedGuardValue?: Record<string, Json>
}

function allCases(): CorpusCase[] {
  const out: CorpusCase[] = []
  for (const f of readdirSync(corpusDir).filter((p) => p.endsWith('.json')).sort()) {
    const root = JSON.parse(readFileSync(join(corpusDir, f), 'utf8')) as { cases: CorpusCase[] }
    out.push(...root.cases)
  }
  return out
}

function parseRule(r: Record<string, Json>): RuleDefinition {
  return {
    id: r.id as string,
    tier: r.tier as RuleDefinition['tier'],
    scope: r.scope as RuleDefinition['scope'],
    scopeTarget: (r.scopeTarget as string) ?? '',
    expression: r.expression as Json,
    action: r.action as RuleDefinition['action'],
    presentation: r.presentation as RuleDefinition['presentation'],
  }
}

// ADR 0146 D2 — corpus skin authoring JSON → the typed skin model → RuleDefinition (mirror of the .NET
// CorpusLoader skin parsing). A skin case exercises the identical downstream compile + eval path.
function compileSkin(s: Record<string, Json>): RuleDefinition {
  const kind = s.kind as string
  if (kind === 'decision-table') return compileDecisionTable(parseDecisionTableSkin(s))
  if (kind === 'formula') return compileFormula(parseFormulaSkin(s))
  throw new Error(`unknown skin kind '${kind}'`)
}

function parseDecisionTableSkin(s: Record<string, Json>): DecisionTableSkin {
  return {
    ruleId: s.ruleId as string,
    scope: s.scope as DecisionTableSkin['scope'],
    scopeTarget: (s.scopeTarget as string) ?? '',
    action: s.action as DecisionTableSkin['action'],
    hitPolicy: s.hitPolicy as DecisionTableSkin['hitPolicy'],
    inputs: s.inputs as string[],
    rows: (s.rows as Array<Record<string, Json>>).map((r) => ({
      when: (r.when as Array<Record<string, Json>>).map(parseCell),
      output: r.output as Json,
      priority: (r.priority as number) ?? 0,
    })),
    noMatch: parseNoMatch(s.noMatch as Record<string, Json>),
  }
}

function parseCell(c: Record<string, Json>): DecisionCell {
  if ('any' in c) return { kind: 'any' }
  if ('op' in c) return { kind: 'compare', op: c.op as string, value: c.value as Json }
  if ('range' in c) {
    const r = c.range as Record<string, Json>
    return { kind: 'range', loInclusive: r.lo ?? null, hiExclusive: r.hi ?? null }
  }
  throw new Error('a decision-table cell must be one of { any | op/value | range }')
}

function parseNoMatch(nm: Record<string, Json>): NoMatch {
  if ('catchAll' in nm) return { kind: 'catch-all' }
  if ('default' in nm) return { kind: 'default', value: nm.default as Json }
  throw new Error('noMatch must declare a `default` value or `catchAll: true` (board F1 — no silent null)')
}

function parseFormulaSkin(s: Record<string, Json>): FormulaSkin {
  return {
    ruleId: s.ruleId as string,
    scope: s.scope as FormulaSkin['scope'],
    scopeTarget: (s.scopeTarget as string) ?? '',
    action: s.action as FormulaSkin['action'],
    inputs: (s.inputs as Array<Record<string, Json>>).map((i) => ({ ref: i.ref as string, type: (i.type as string) ?? 'any' })),
    expression: s.expression as Json,
  }
}

function clockOf(c: CorpusCase): () => Date {
  const clockMs = c.clock ? new Date(c.clock).getTime() : new Date('2026-06-30T00:00:00Z').getTime()
  return () => new Date(clockMs)
}

/**
 * The rules the case DECLARES — the exact list handed to the compiler. Ticket 193 review: the
 * runner needs this separately from `runCase` so it can assert the compiled graph introduced no
 * rule the case never declared.
 */
function declaredRules(c: CorpusCase): RuleDefinition[] {
  return c.skin ? [compileSkin(c.skin)] : (c.definitionRules ?? []).map(parseRule)
}

function runCase(c: CorpusCase) {
  const rules = declaredRules(c)
  const compiled = compile(rules)
  const graph = new FormRuleGraph(compiled, clockOf(c), testAdmission)
  const result = graph.evaluateInstance(RuleInstance.fromJsonText(JSON.stringify(c.instance)))
  return { compiled, result }
}

// Ticket 162: a case pinning a publish-time refusal — return the stable code compile raises.
function compileRefusalCode(c: CorpusCase): string {
  try {
    compile((c.definitionRules ?? []).map(parseRule))
  } catch (e) {
    if (e instanceof CompileError) return e.code
    throw e
  }
  throw new Error(`case '${c.name}' expected a compile refusal and none was raised`)
}

// Ticket 162: a case evaluating one rule through the guard tier (flat context bag; no tables).
function guardValueOutcome(c: CorpusCase): string {
  const rule = (c.definitionRules ?? []).map(parseRule).find((r) => r.id === c.guardValue)
  if (!rule) throw new Error(`case '${c.name}': guardValue names unknown rule '${c.guardValue}'`)
  return serializeComputedValue(new GuardEvaluator(clockOf(c)).evaluateValue(rule, RuleContextSnapshot.fromJsonText(JSON.stringify(c.instance)), testAdmission))
}

describe('SPINE-1 conformance corpus (TS tier — byte-identical to .NET)', () => {
  for (const c of allCases()) {
    it(c.name, () => {
      if (c.expectedCompileError) {
        expect(compileRefusalCode(c)).toBe(c.expectedCompileError.code)
        return
      }
      if (c.guardValue) {
        expect(guardValueOutcome(c)).toBe(write(c.expectedGuardValue as Json))
        return
      }
      const { compiled, result } = runCase(c)

      // ADR 0146 D2 — pin the skin compiler's pre-lowering expression byte-identical to the .NET tier.
      if (c.expectedCompiledExpression) {
        for (const [ruleId, expected] of Object.entries(c.expectedCompiledExpression)) {
          const rule = compiled.rules.find((r) => r.source.id === ruleId)
          expect(rule, `expectedCompiledExpression names unknown rule '${ruleId}'`).toBeDefined()
          const produced = typeof rule!.source.expression === 'string'
            ? (JSON.parse(rule!.source.expression) as Json)
            : (rule!.source.expression as Json)
          expect(write(produced)).toBe(write(expected))
        }
      }

      // EXACT compiled set, not a lower bound (ticket 193 review): expectedCompiledExpression /
      // expectedAst name only the rules a case cares to pin, so neither notices a rule the compiler
      // INVENTED. Every compiled rule must trace back to a rule the case declared, once. (Subset, not
      // equality: the compiler deliberately drops Tier-1 JsonSchema rules — the kernel validator owns
      // those — so a declared rule legitimately need not compile.)
      const declaredIds = new Set(declaredRules(c).map((r) => r.id))
      const compiledIds = compiled.rules.map((r) => r.source.id)
      expect(compiledIds.filter((id) => !declaredIds.has(id))).toEqual([])
      expect(new Set(compiledIds).size).toBe(compiledIds.length)

      if (c.expectedAst) {
        for (const [ruleId, expected] of Object.entries(c.expectedAst)) {
          const rule = compiled.rules.find((r) => r.source.id === ruleId)
          expect(rule, `expectedAst names unknown rule '${ruleId}'`).toBeDefined()
          expect(write(rule!.ast as Json)).toBe(write(expected))
        }
      }

      // The outcome key set is asserted WHOLE before the values (ticket 193 review): declared keys
      // were a lower bound, so a regression emitting an unintended extra outcome while satisfying
      // every declared expectation kept the corpus green.
      const expectedOutcomes = c.expectedOutcomes ?? {}
      expect([...result.byRule.keys()].sort()).toEqual(Object.keys(expectedOutcomes).sort())
      for (const [ruleKey, expected] of Object.entries(expectedOutcomes)) {
        expect(serializeOutcome(result.byRule.get(ruleKey)!)).toBe(write(expected))
      }
    })
  }

  it('emits the cross-tier artifact', () => {
    const artifact: Record<string, Record<string, string>> = {}
    for (const c of allCases()) {
      if (c.expectedCompileError) {
        artifact[c.name] = { '(compile)': compileRefusalCode(c) }
        continue
      }
      if (c.guardValue) {
        artifact[c.name] = { [c.guardValue]: guardValueOutcome(c) }
        continue
      }
      const { result } = runCase(c)
      // Ticket 193 review: iterate the PRODUCED keys, not the declared ones. Emitting only
      // `expectedOutcomes` made the cross-tier artifact diff (runners/run-shared.mjs) a lower bound
      // as well — an extra outcome on BOTH tiers was invisible to it twice over.
      const perCase: Record<string, string> = {}
      for (const ruleKey of [...result.byRule.keys()].sort()) {
        perCase[ruleKey] = serializeOutcome(result.byRule.get(ruleKey)!)
      }
      artifact[c.name] = perCase
    }
    try {
      mkdirSync(artifactDir, { recursive: true })
      writeFileSync(join(artifactDir, 'ts-outcomes.json'), JSON.stringify(artifact, null, 2))
    } catch {
      // best-effort
    }
  })
})

src/guard.test.ts.source:
import { describe, expect, it } from 'vitest'

import { Codes } from './codes.js'
import { GuardEvaluator, RuleContextSnapshot } from './guard.js'
import type { Json, RuleDefinition } from './model.js'
import { admitEnvironment as admitTestEnvironment, fieldReadEffect as testFieldRead, lentGrammar as testGrammar } from './environment.js'
import { builtInFunctions as testBuiltIns } from './functions.js'
// The suite's own borrower: the whole register, every scope token, every phase (T-590 rules-eng-26).
const testAdmission = admitTestEnvironment({ borrower: 'rule-engine-tests', grammar: testGrammar, variables: { field: 'test', row: 'test', wf: 'test', timer: 'test' }, operations: testBuiltIns.map((f) => f.key), effects: [testFieldRead], missingValues: 'missing-field-reads-null', timeSource: 'injected-test-clock', timeZone: 'utc', phases: { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }, replay: 'deterministic' }).forPhase('Run')

const fixedClock = () => new Date('2026-06-30T00:00:00.000Z')
const snapshot = (value: Record<string, Json>) => RuleContextSnapshot.fromJsonText(JSON.stringify(value))

function rule(id: string, expression: Json, action: RuleDefinition['action'] = 'Validate'): RuleDefinition {
  return {
    id,
    tier: 'JsonLogic',
    scope: 'Schema',
    scopeTarget: '',
    action,
    expression,
  }
}

describe('GuardEvaluator.evaluateGuard', () => {
  const evaluator = new GuardEvaluator(fixedClock)
  const minimumAmount = rule('guard.minimum-amount', { '>=': [{ var: 'amount' }, 100] })

  it('accepts a boundary value and rejects a lower value with the rule id', () => {
    expect(evaluator.evaluateGuard(minimumAmount, snapshot({ amount: 100 }), testAdmission)).toEqual({ ok: true })
    expect(evaluator.evaluateGuard(minimumAmount, snapshot({ amount: 99 }), testAdmission)).toEqual({
      ok: false,
      error: { code: 'guard.minimum-amount', params: {} },
    })
  })

  it('fails closed with typed results for an empty context and a pending dependency', () => {
    expect(evaluator.evaluateGuard(minimumAmount, snapshot({}), testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.typeError, params: { reason: 'null-as-number' } },
    })
    expect(evaluator.evaluateGuard(minimumAmount, snapshot({ amount: { '@pending': true } }), testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.pendingAtSave, params: {} },
    })
  })

  it('recognizes only the exact pending sentinel, never similarly shaped JSON values', () => {
    const valueGuard = rule('guard.pending-shape', { var: 'amount' })

    expect(evaluator.evaluateGuard(valueGuard, snapshot({ amount: { '@pending': true, extra: 1 } }), testAdmission)).toEqual({ ok: true })
    expect(evaluator.evaluateGuard(valueGuard, snapshot({ amount: { '@pending': false } }), testAdmission)).toEqual({ ok: true })
    expect(evaluator.evaluateGuard(valueGuard, snapshot({ amount: ['not pending'] }), testAdmission)).toEqual({ ok: true })
    expect(evaluator.evaluateGuard(valueGuard, snapshot({ amount: null }), testAdmission)).toEqual({
      ok: false,
      error: { code: 'guard.pending-shape', params: {} },
    })
  })

  it('refuses row-scoped references instead of treating the flat bag as a row', () => {
    const rowGuard = { ...rule('guard.no-row-scope', { var: 'row.amount' }), scope: 'Row' as const, scopeTarget: 'items/amount' }

    expect(evaluator.evaluateGuard(rowGuard, snapshot({ amount: 100 }), testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.badReference, params: { path: 'row.amount' } },
    })
  })

  it('resolves field-prefixed references from the matching flat context member', () => {
    expect(evaluator.evaluateGuard(rule('guard.field-scope', { var: 'field.amount' }), snapshot({ amount: 100 }), testAdmission)).toEqual({ ok: true })
    expect(evaluator.evaluateGuard(rule('guard.plain-scope', { var: 'amount' }), snapshot({ amount: 100 }), testAdmission)).toEqual({ ok: true })
  })

  it('returns a stable error result for an invalid division expression', () => {
    expect(evaluator.evaluateGuard(rule('guard.invalid', { '/': [1, 0] }), snapshot({}), testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.divByZero, params: {} },
    })
  })

  it('refuses an accessor-backed host context without invoking its getter', () => {
    let invoked = false
    const context = {} as Record<string, Json>
    Object.defineProperty(context, 'amount', { enumerable: true, get: () => {
      invoked = true
      throw new Error('host callback ran')
    } })

    expect(evaluator.evaluateGuard(minimumAmount, context as unknown as RuleContextSnapshot, testAdmission)).toEqual({
      ok: false,
      error: { code: 'rule.context_snapshot_required', params: {} },
    })
    expect(invoked).toBe(false)
  })

  it('refuses a proxied host context before reflective traps can run', () => {
    let invoked = false
    const context = new Proxy({ amount: 100 } as Record<string, Json>, {
      getPrototypeOf: () => {
        invoked = true
        throw new Error('proxy trap ran')
      },
      ownKeys: () => {
        invoked = true
        throw new Error('proxy trap ran')
      },
      getOwnPropertyDescriptor: () => {
        invoked = true
        throw new Error('proxy trap ran')
      },
    })

    expect(evaluator.evaluateGuard(minimumAmount, context as unknown as RuleContextSnapshot, testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.contextSnapshotRequired, params: {} },
    })
    expect(invoked).toBe(false)
  })

  it('refuses a JavaScript-forged context snapshot without reading its supplied values', () => {
    let invoked = false
    const UnsafeConstructor = RuleContextSnapshot as unknown as new (values: Record<string, Json>) => RuleContextSnapshot
    const forged = new UnsafeConstructor(new Proxy({ amount: 100 } as Record<string, Json>, {
      get: () => {
        invoked = true
        throw new Error('forged values ran')
      },
    }))

    expect(evaluator.evaluateGuard(minimumAmount, forged, testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.contextSnapshotRequired, params: {} },
    })
    expect(invoked).toBe(false)
  })

  it('does not read a replacement values getter on a branded snapshot', () => {
    let invoked = false
    const context = RuleContextSnapshot.fromJsonText('{"amount":100}')
    Object.defineProperty(context, 'values', { get: () => {
      invoked = true
      throw new Error('replacement values ran')
    } })

    expect(evaluator.evaluateGuard(minimumAmount, context, testAdmission)).toEqual({ ok: true })
    expect(invoked).toBe(false)
  })

  it('refuses a JSON context over the finite node envelope before evaluation', () => {
    const overLimit = JSON.stringify({ values: Array.from({ length: 4_999 }, () => 0) })

    expect(() => RuleContextSnapshot.fromJsonText(overLimit)).toThrow(RangeError)
  })

  it('uses UTF-8 bytes rather than JavaScript character count at the input boundary', () => {
    const prefix = '{"payload":"'
    const suffix = '"}'
    const asciiAtLimit = `${prefix}${'a'.repeat(262_144 - prefix.length - suffix.length)}${suffix}`
    const nonAsciiAtLimit = `${prefix}${'é'.repeat((262_144 - prefix.length - suffix.length) / 2)}${suffix}`

    expect(() => RuleContextSnapshot.fromJsonText(asciiAtLimit)).not.toThrow()
    expect(() => RuleContextSnapshot.fromJsonText(`${asciiAtLimit.slice(0, -2)}a${suffix}`)).toThrow(RangeError)
    expect(() => RuleContextSnapshot.fromJsonText(nonAsciiAtLimit)).not.toThrow()
    expect(() => RuleContextSnapshot.fromJsonText(`${nonAsciiAtLimit.slice(0, -2)}é${suffix}`)).toThrow(RangeError)
  })

  it('labels malformed JSON contexts and refuses non-object JSON contexts', () => {
    expect(() => RuleContextSnapshot.fromJsonText('{')).toThrow('rule context is not valid JSON')
    expect(() => RuleContextSnapshot.fromJsonText('null')).toThrow('rule context must be a JSON object')
    expect(() => RuleContextSnapshot.fromJsonText('[]')).toThrow('rule context must be a JSON object')
  })

  it('refuses null contexts with the snapshot-required result rather than inspecting them', () => {
    expect(evaluator.evaluateGuard(minimumAmount, null as unknown as RuleContextSnapshot, testAdmission)).toEqual({
      ok: false,
      error: { code: Codes.contextSnapshotRequired, params: {} },
    })
  })
})

describe('GuardEvaluator.evaluateValue', () => {
  const evaluator = new GuardEvaluator(fixedClock)

  it('resolves a deterministic expression', () => {
    expect(evaluator.evaluateValue(rule('value.total', { '+': [{ var: 'amount' }, 1] }, 'Compute'), snapshot({
      amount: 41,
    }), testAdmission)).toEqual({ state: 'Resolved', value: 42 })
  })

  it('resolves a missing value as null and preserves a pending value as Pending', () => {
    const reference = rule('value.reference', { var: 'amount' }, 'Compute')

    expect(evaluator.evaluateValue(reference, snapshot({}), testAdmission)).toEqual({ state: 'Resolved', value: null })
    expect(evaluator.evaluateValue(reference, snapshot({ amount: { '@pending': true } }), testAdmission)).toEqual({
      state: 'Pending',
    })
  })

  it('refuses a forged value-evaluation snapshot before reading its supplied values', () => {
    let invoked = false
    const UnsafeConstructor = RuleContextSnapshot as unknown as new () => RuleContextSnapshot
    const forged = new UnsafeConstructor()
    Object.defineProperty(forged, 'amount', { get: () => {
      invoked = true
      throw new Error('forged values ran')
    } })

    expect(evaluator.evaluateValue(rule('value.requires-snapshot', { var: 'amount' }, 'Compute'), forged, testAdmission)).toEqual({
      state: 'Error',
      error: { code: Codes.contextSnapshotRequired, params: {} },
    })
    expect(invoked).toBe(false)
  })

  it('returns the stable error result for an invalid division expression', () => {
    expect(evaluator.evaluateValue(rule('value.invalid', { '/': [1, 0] }, 'Compute'), snapshot({}), testAdmission)).toEqual({
      state: 'Error',
      error: { code: Codes.divByZero, params: {} },
    })
  })
})

src/__tests__/trace.test.ts.source:
/**
 * ADR 0146 D10 — interactive explainability traces (board F2), TS tier. Mirror of the .NET `RuleTraceTests`:
 * a trace is emitted on the interactive path (opt-in projection) and traceless otherwise; the authority
 * filter darkens field references (redact / shredded-subject hash); and a field VALUE is NEVER in a trace param.
 */
import { describe, it, expect } from 'vitest'

import { compile } from '../compiler.js'
import { FormRuleGraph } from '../graph.js'
import { GuardEvaluator, RuleContextSnapshot } from '../guard.js'
import { RuleInstance } from '../instance.js'
import type { Json, RuleDefinition } from '../model.js'
import {
  buildFormTrace, buildGuardTrace, RuleTraceCodes, passThroughTraceFilter,
  type TraceAuthorityFilter, type TraceFieldDisclosure,
} from '../trace.js'
import { admitEnvironment as admitTestEnvironment, fieldReadEffect as testFieldRead, lentGrammar as testGrammar } from '../environment.js'
import { builtInFunctions as testBuiltIns } from '../functions.js'
import { compileDecisionTable, type DecisionTableSkin } from '../skins/decision-table.js'
// The suite's own borrower: the whole register, every scope token, every phase (T-590 rules-eng-26).
const testAdmission = admitTestEnvironment({ borrower: 'rule-engine-tests', grammar: testGrammar, variables: { field: 'test', row: 'test', wf: 'test', timer: 'test' }, operations: testBuiltIns.map((f) => f.key), effects: [testFieldRead], missingValues: 'missing-field-reads-null', timeSource: 'injected-test-clock', timeZone: 'utc', phases: { AuthoringValidation: true, PublishValidation: true, Render: true, Submission: true, Run: true, SignOff: true }, replay: 'deterministic' }).forPhase('Run')

const hideHighEarnerComp: RuleDefinition = {
  id: 'vis.comp', tier: 'JsonLogic', scope: 'Section', scopeTarget: 'comp',
  expression: { '<=': [{ var: 'salary' }, 100000] }, action: 'Visibility',
}
const fixedClock = () => new Date('2026-06-30T00:00:00.000Z')
const snapshot = (value: Record<string, Json>) => RuleContextSnapshot.fromJsonText(JSON.stringify(value))

function evaluate(rule: RuleDefinition, instance: Record<string, Json>) {
  const compiled = compile([rule])
  const graph = new FormRuleGraph(compiled, fixedClock, testAdmission)
  const result = graph.evaluateInstance(RuleInstance.fromJsonText(JSON.stringify(instance)))
  return { compiled, result }
}

function denyFilter(field: string): TraceAuthorityFilter {
  return { disclose: (name): TraceFieldDisclosure => (name === field ? 'redact' : 'show') }
}
function shredFilter(field: string): TraceAuthorityFilter {
  return { disclose: (name): TraceFieldDisclosure => (name === field ? 'hash' : 'show') }
}

describe('ADR 0146 D10 traces', () => {
  it('emits a trace on the interactive path (opt-in projection); the eval itself is traceless', () => {
    const { compiled, result } = evaluate(hideHighEarnerComp, { salary: 150000 })
    const trace = buildFormTrace(compiled, result)
    expect(trace).toHaveLength(1)
    expect(trace[0].ruleId).toBe('vis.comp')
  })

  it('high earner is hidden; the trace carries the code + field ref, NEVER the value', () => {
    const { compiled, result } = evaluate(hideHighEarnerComp, { salary: 150000 })
    const entry = buildFormTrace(compiled, result, passThroughTraceFilter)[0]
    expect(entry.code).toBe(RuleTraceCodes.hidden)
    expect(entry.params.reads).toBe('salary')
    expect(entry.target).toBe('section:comp')
    for (const v of Object.values(entry.params)) {
      expect(v).not.toContain('150000')
      expect(v).not.toContain('100000')
    }
  })

  it('the authority filter redacts an unreadable field reference', () => {
    const { compiled, result } = evaluate(hideHighEarnerComp, { salary: 150000 })
    const entry = buildFormTrace(compiled, result, denyFilter('salary'))[0]
    expect(entry.code).toBe(RuleTraceCodes.hidden)
    expect(entry.params.reads).toBe('[redacted]')
  })

  it('a shredded subject darkens the reference to a reference+hash form', () => {
    const { compiled, result } = evaluate(hideHighEarnerComp, { salary: 150000 })
    const entry = buildFormTrace(compiled, result, shredFilter('salary'))[0]
    expect(entry.params.reads.startsWith('#')).toBe(true)
    // Cross-tier anchor: the SAME literal is pinned in the .NET tier's trace test — byte-identical hashing.
    expect(entry.params.reads).toBe('#8561b279')
    expect(entry.params.reads).not.toContain('salary')
  })

  it('validation failure carries the cause code, never the value', () => {
    const rule: RuleDefinition = { id: 'v.qty', tier: 'JsonLogic', scope: 'Field', scopeTarget: 'qty', expression: { '>': [{ var: 'qty' }, 0] }, action: 'Validate' }
    const { compiled, result } = evaluate(rule, { qty: -3 })
    const entry = buildFormTrace(compiled, result)[0]
    expect(entry.code).toBe(RuleTraceCodes.validationFailed)
    expect(entry.params.cause).toBe('v.qty')
    expect(Object.values(entry.params).join('|')).not.toContain('-3')
  })

  it('compute value carries the computed code but not the computed value', () => {
    const rule: RuleDefinition = { id: 'c.total', tier: 'JsonLogic', scope: 'Field', scopeTarget: 'total', expression: { '+': [{ var: 'qty' }, { var: 'extra' }] }, action: 'Compute' }
    const { compiled, result } = evaluate(rule, { qty: 3, extra: 4 })
    const entry = buildFormTrace(compiled, result)[0]
    expect(entry.code).toBe(RuleTraceCodes.valueComputed)
    expect(entry.params.reads.split(',').sort().join(',')).toBe('extra,qty')
    expect(Object.values(entry.params).join('|')).not.toContain('7')
  })

  it('guard traces carry the code + field ref (passed / failed)', () => {
    const guard: RuleDefinition = { id: 'g.amount', tier: 'JsonLogic', scope: 'Schema', scopeTarget: '', expression: { '>': [{ var: 'amount' }, 5000] }, action: 'Validate' }
    const evaluator = new GuardEvaluator(fixedClock)

    const pass = evaluator.evaluateGuard(guard, snapshot({ amount: 7000 }), testAdmission)
    const passTrace = buildGuardTrace(guard, pass)
    expect(passTrace.code).toBe(RuleTraceCodes.guardPassed)
    expect(passTrace.params.reads).toBe('amount')
    expect(passTrace.target).toBe('guard:g.amount')

    const fail = evaluator.evaluateGuard(guard, snapshot({ amount: 3000 }), testAdmission)
    const failTrace = buildGuardTrace(guard, fail)
    expect(failTrace.code).toBe(RuleTraceCodes.guardFailed)
    expect(failTrace.params.cause).toBe('g.amount')
    expect(Object.values(failTrace.params).join('|')).not.toContain('3000')
  })
})

describe('T-591 decision trace', () => {
  it.each(['priority', 'first-match'] as const)('rules-run-2: a decision-table outcome names the deciding rule, its reads and its declared %s hit policy, never a value', (hitPolicy) => {
    const table: DecisionTableSkin = {
      ruleId: 'tier.table', scope: 'Field', scopeTarget: 'tier', action: 'Compute', hitPolicy, inputs: ['amount'],
      rows: [{ when: [{ kind: 'compare', op: '>=', value: 1000 }], output: 'gold', priority: 1 }, { when: [{ kind: 'compare', op: '>=', value: 100 }], output: 'silver', priority: 5 }],
      noMatch: { kind: 'default', value: 'bronze' },
    }
    const formula: RuleDefinition = { id: 'limit.check', tier: 'JsonLogic', scope: 'Field', scopeTarget: 'limit', expression: { '<=': [{ var: 'amount' }, { var: 'limit' }] }, action: 'Validate' }
    const compiled = compile([compileDecisionTable(table), formula])
    const result = new FormRuleGraph(compiled, fixedClock, testAdmission).evaluateInstance(RuleInstance.fromJsonText(JSON.stringify({ amount: 1500, limit: 10 })))
    const trace = buildFormTrace(compiled, result, passThroughTraceFilter, [table])
    const decided = trace.find((entry) => entry.ruleId === 'tier.table')!
    expect(decided.code).toBe(RuleTraceCodes.valueComputed)
    expect(decided.params).toMatchObject({ rule: 'tier.table', reads: 'amount', hitPolicy })
    expect(trace.find((entry) => entry.ruleId === 'limit.check')!.params.hitPolicy).toBeUndefined()
    const params = trace.flatMap((entry) => Object.values(entry.params)).join('|')
    for (const leaked of ['1500', 'gold', 'silver', 'bronze']) expect(params).not.toContain(leaked)
  })
})

